def slugify(text: str) -> str:
    text = text.lower()
    text = re.sub(r'[^a-z0-9]+', '-', text)
    return text.strip('-')

def extract_writer(author_proof: str, verification_notes: str) -> str:
    text_to_check = verification_notes if (verification_notes and "daftar penulis:" in verification_notes) else (author_proof or "")
    if "daftar penulis:" in text_to_check:
        writer_part = text_to_check.split("daftar penulis:")[1].strip()
        writer = re.sub(r'\(.*?\)', '', writer_part).strip(' ,;)')
        return writer if writer else None
    return None

